        "eq": [
          {
            "var": "phase"
          },
          "\"delete\""
        ]
      },
      "label": "Request old database deletion"
    },
    {
      "id": "metadata",
      "when": {
        "any": [
          {
            "eq": [
              {
                "var": "phase"
              },
              "\"metadata\""
            ]
          },
          {
            "eq": [
              {
                "var": "phase"
              },
              "\"metadataReady\""
            ]
          }
        ]
      },
      "label": "Read local item metadata"
    },
    {
      "id": "close-failed",
      "when": {
        "eq": [
          {
            "var": "phase"
          },
          "\"closeFailed\""
        ]
      },
      "label": "Close database after failure"
    },
    {
      "id": "all",
      "when": true,
      "label": "Check and migrate the local library"
    }
  ],
  "step": [
    {
      "id": "load",
      "when": {
        "eq": [
          {
            "action": true
          },
          "StartLoad"
        ]
      },
      "label": "Browser loads"
    },
    {
      "id": "read-failed",
      "when": {
        "any": [
          {
            "eq": [
              {
                "action": true
              },
              "BytesUnavailable"
            ]
          },
          {
            "eq": [
              {
                "action": true
              },
              "BytesError"
            ]
          },
          {
            "eq": [
              {
                "action": true
              },
              "BytesAbort"
            ]
          }
        ]
      },
      "label": "Local bytes unavailable"
    },
    {
      "id": "upload-failed",
      "when": {
        "eq": [
          {
            "action": true
          },
          "UploadFailure"
        ]
      },
      "label": "Upload fails"
    },
    {
      "id": "upload-succeeds",
      "when": {
        "eq": [
          {
            "action": true
          },
          "UploadSuccess"
        ]
      },
      "label": "Upload succeeds"
    },
    {
      "id": "skip-existing",
      "when": {
        "eq": [
          {
            "action": true
          },
          "SkipExisting"
        ]
      },
      "label": "Same kind and name already shared"
    },
    {
      "id": "mark",
      "when": {
        "eq": [
          {
            "action": true
          },
          "MarkerWritten"
        ]
      },
      "label": "Write completion flag"
    },
    {
      "id": "delete",
      "when": {
        "eq": [
          {
            "action": true
          },
          "DeleteDatabase"
        ]
      },
      "label": "Request database deletion"
    },
    {
      "id": "request-ready",
      "when": {
        "any": [
          {
            "eq": [
              {
                "action": true
              },
              "MetadataRequestSuccess"
            ]
          },
          {
            "eq": [
              {
                "action": true
              },
              "BytesRequestSuccess"
            ]
          }
        ]
      },
      "label": "Request succeeds; wait for transaction"
    },
    {
      "id": "read-complete",
      "when": {
        "any": [
          {
            "eq": [
              {
                "action": true
              },
              "ReadMetadata"
            ]
          },
          {
            "eq": [
              {
                "action": true
              },
              "ReadBytes"
            ]
          }
        ]
      },
      "label": "Read transaction completes"
    },
    {
      "id": "metadata-failed",
      "when": {
        "any": [
          {
            "eq": [
              {
                "action": true
              },
              "MetadataError"
            ]
          },
          {
            "eq": [
              {
                "action": true
              },
              "MetadataAbort"
            ]
          }
        ]
      },
      "label": "Metadata read fails"
    },
    {
      "id": "close",
      "when": {
        "any": [
          {
            "eq": [
              {
                "action": true
              },
              "CloseAfterFailure"
            ]
          },
          {
            "eq": [
              {
                "action": true
              },
              "CloseAfterSuccess"
            ]
          }
        ]
      },
      "label": "Close database"
    },
    {
      "id": "all",
      "when": true,
      "label": "Continue migration or return"
    }
  ]
}

statements.old_text:
EmptyLibraryCompleted ==
    /\ phase = "idle" /\ oldDatabase /\ localItems = {}
    /\ flag /\ deleteIssued /\ writes.upload = 0

statements.new_text:
EmptyLibraryCompleted ==
    /\ phase = "idle" /\ oldDatabase /\ localItems = {}
    /\ flag /\ deleteIssued /\ writes.upload = 0

MetadataFailureRetained ==
    /\ phase = "idle" /\ ~metadataOK /\ Missing # {}
    /\ ~flag /\ ~deleteIssued

RetryCompletes ==
    /\ phase = "idle" /\ loads = 2 /\ retryItems # {}
    /\ flag /\ deleteIssued /\ AllShared
